_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _check_base(base):
    if not isinstance(base, int) or not 2 <= base <= 36:
        raise ValueError("base must be an integer from 2 to 36")


def to_base(number, base):
    _check_base(base)
    if number == 0:
        return "0"

    magnitude = abs(number)
    digits = []
    while magnitude:
        magnitude, remainder = divmod(magnitude, base)
        digits.append(_DIGITS[remainder])
    if number < 0:
        digits.append("-")
    return "".join(reversed(digits))


def from_base(text, base):
    _check_base(base)
    negative = text.startswith("-")
    digits = text[1:] if negative else text
    if not digits or not digits.isascii():
        raise ValueError("expected ASCII digits")

    number = 0
    for char in digits.lower():
        value = _DIGITS.find(char)
        if not 0 <= value < base:
            raise ValueError(f"invalid digit {char!r} for base {base}")
        number = number * base + value
    return -number if negative else number
